    "ops.last_accepted": ["Последний приём провайдером","Last provider acceptance"],
    "ops.workers": ["Фоновые процессы","Background processes"],
    "ops.times_msk": ["Все отметки времени показаны по Москве. Состояние проверяется при открытии и обновлении этой панели.","All timestamps use Moscow time. Status is checked when this panel opens or refreshes."],
    "execution.title": ["План ребалансировки","Rebalancing plan"],
    "execution.help": ["Подготовьте план по сохранённой стратегии, актуальному составу счёта и текущим котировкам. Сначала проверьте шаги и издержки; каждое исполнение запускается отдельно.","Prepare a plan using your saved strategy, current account holdings and current quotes. Review the steps and costs first; each execution is started separately."],
    "execution.prepare": ["Подготовить план","Prepare plan"],
    "execution.history": ["История исполнений","Execution history"],
    "execution.error.policy": ["В стратегии не заполнены обязательные ограничения. Укажите личные условия и сохраните их перед расчётом.","Required strategy constraints are incomplete. Enter and save your personal parameters before calculating."],
    "execution.error.research": ["Нужно рассчитанное исследование текущей версии стратегии, сохранённое не более 24 часов назад.","A completed research run for the current strategy version, saved within the last 24 hours, is required."],
    "execution.error.snapshot": ["Обновите счёт и дождитесь подтверждённого снимка, прежде чем рассчитывать план.","Refresh the account and wait for a confirmed snapshot before calculating the plan."],
    "execution.error.connection": ["Для плана подключите свой брокерский счёт.","Connect your broker account to prepare a plan."],
    "execution.error.quote": ["Котировка неполная или устарела. Получите новые данные и пересчитайте план.","The quote is incomplete or out of date. Obtain fresh data and recalculate the plan."],
    "execution.error.moved": ["Цена вышла за согласованный лимит. Этот шаг не отправлен; пересчитайте план.","The price moved outside the agreed limit. This step was not submitted; recalculate the plan."],
    "execution.error.cost": ["Подтверждённые издержки превышают предел плана. Проверьте условия и пересчитайте его.","Confirmed costs exceed the plan's limit. Review the parameters and recalculate."],
    "execution.error.expired": ["Срок подтверждения плана истёк. Пересчитайте его по новым данным.","The plan's confirmation window has expired. Recalculate using fresh data."],
    "execution.error.disabled": ["Этот режим исполнения не включён оператором. Проверьте доступные возможности.","The operator has not enabled this execution mode. Check the available capabilities."],
    "execution.error.evidence": ["Исходные данные исследования изменились. Сначала выполните новое исследование.","The research inputs have changed. Run new research first."],
    "execution.error.portfolio": ["Состав счёта или свободные средства изменились. Обновите данные и пересчитайте план.","Account holdings or available cash have changed. Refresh the data and recalculate the plan."],
    "execution.error.held": ["Не подтверждены данные по имеющимся позициям. План нельзя завершить до получения этих сведений.","Evidence for existing positions is unconfirmed. The plan cannot be completed until this data is available."],
    "execution.error.permission": ["Источник не подтвердил доступность операции с инструментом. Этот шаг не разрешён.","The source has not confirmed that this instrument can be traded. This step is not permitted."],
    "execution.save_first": ["Сначала сохраните стратегию и дождитесь подтверждения сервера.","Save the strategy and wait for server confirmation first."],
    "execution.loading": ["Проверяем условия плана…","Checking plan requirements…"],
    "execution.no_research": ["Для этой версии стратегии нет рассчитанного исследования. Выполните и сохраните новое исследование, затем вернитесь к плану.","There is no completed research for this strategy version. Run and save new research, then return to the plan."],
    "execution.shadow_notice": ["Теневой режим: план использует актуальный счёт и текущие котировки, а исполнение моделируется в отдельном журнале. Реальные заявки брокеру не отправляются. Это не повтор исторического исследования и не прогноз прибыли.","Shadow mode uses the current account and current quotes, with fills simulated in a separate ledger. No live broker orders are submitted. This is not a replay of historical research or a profit forecast."],
    "execution.research": ["Исследование текущей стратегии","Research for the current strategy"],
    "execution.inputs": ["Используется выбранное исследование не старше 24 часов. Комиссия и допуск на проскальзывание берутся из его сохранённых условий; состав счёта, доступные деньги и котировки проверяются заново. Дневной предел действует за календарный день МСК; незавершённые исполнения также резервируют лимит.","The selected research must be no more than 24 hours old. Commission and slippage allowances come from its saved parameters; account holdings, available cash and quotes are checked again. The daily limit uses the MSK calendar day; unfinished executions also reserve capacity."],
    "execution.order_cap": ["Предел одного шага","Per-step limit"],
    "execution.daily_cap": ["Дневной предел оборота · МСК","Daily turnover limit · MSK"],
    "execution.validity": ["Окно подтверждения","Confirmation window"],
    "execution.two_minutes": ["2 минуты после расчёта","2 minutes after calculation"],
    "execution.calculate": ["Рассчитать шаги","Calculate steps"],
    "execution.refresh_snapshot": ["Обновить снимок счёта","Refresh account snapshot"],
    "execution.nav": ["Наблюдаемая стоимость счёта","Observed account value"],
